const tiles=blankFloor(30,22),props:Prop[]=[];
fill(tiles,14,1,15,20,2);
for(let x=20;x<=28;x++){tiles[2][x]=4;tiles[9][x]=4;}for(let y=2;y<=9;y++){tiles[y][28]=4;if(y!==6)tiles[y][20]=4;}
