emit(){this.onChange(this.snapshot());}
fixText(text:string){let out=text;for(let i=0;i<2&&/[\u00c3\u00c2]/.test(out);i++){try{const bytes=Array.from(out,ch=>`%${ch.charCodeAt(0).toString(16).padStart(2,'0')}`).join('');out=decodeURIComponent(bytes);}catch{return out;}}return out;}
