/* ---------- som ---------- */
scenarioTrack(){const files:Partial<Record<Zone,string>>={world:'1. Primeiro cenário — Bosque Nevado.mp3',eclipse:'3. Terceiro cenário — Floresta das Trevas.mp3',bastion:'4. Quarto cenário — Floresta da Chuva.mp3',sanctum:'5. Quinto cenário — Campos Abertos.mp3',aerie:'6. Sexto cenário — Deserto das Tempestades.mp3',sunken:'6. Sexto cenário — Deserto das Tempestades.mp3',grove:'4. Quarto cenário — Floresta da Chuva.mp3'};const lavaZones=new Set<Zone>(['north','citadel1','citadel2','citadel']);const caveZones=new Set<Zone>(['cave1','cave2','temple','grotto','dojo','lightcave','tidecave']);const file=this.zone==='south'?SOUTH_TRACK[this.region]??null:lavaZones.has(this.zone)?'2. Segundo cenário — Cidadela de Lava.mp3':caveZones.has(this.zone)?'todas as cavernas.mp3':files[this.zone]??(this.outdoors?null:'todas as cavernas.mp3');return file?`soundtrack/${encodeURI(file)}`:null;}
stopMusic(){this.musicFadeToken++;if(this.musicFadeRaf)cancelAnimationFrame(this.musicFadeRaf);this.musicFadeRaf=0;for(const audio of[this.musicAudio,this.musicNext]){if(audio){audio.pause();audio.currentTime=0;}}this.musicAudio=null;this.musicNext=null;this.musicTrack='';this.musicLoopPending=false;}
