powerShotSound(kind:Arrow){this.thump(150,30,.6,.55,.4);if(!this.sound||!this.audio)return;const a=this.audio,now=a.currentTime;const n=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();n.buffer=this.noiseData(a);f.type='lowpass';f.frequency.setValueAtTime(2400,now);f.frequency.exponentialRampToValueAtTime(180,now+.32);g.gain.setValueAtTime(.42,now);g.gain.exponentialRampToValueAtTime(.0001,now+.34);n.connect(f);f.connect(g);g.connect(a.destination);n.start(now);n.stop(now+.36);const o=a.createOscillator(),og=a.createGain();o.type='sawtooth';o.frequency.setValueAtTime(90,now);o.frequency.exponentialRampToValueAtTime(42,now+.45);og.gain.setValueAtTime(.12,now);og.gain.exponentialRampToValueAtTime(.0001,now+.45);o.connect(og);og.connect(a.destination);o.start(now);o.stop(now+.47);const base=kind==='ice'?1568:kind==='light'?1760:kind==='fire'?1175:1320;for(const[fq,dt,gn]of[[base,0,.06],[base*1.5,.04,.04],[base*2,.08,.025]] as const){const s2=a.createOscillator(),sg=a.createGain();s2.type='triangle';s2.frequency.setValueAtTime(fq,now+dt);s2.frequency.exponentialRampToValueAtTime(fq*.7,now+dt+.4);sg.gain.setValueAtTime(gn,now+dt);sg.gain.exponentialRampToValueAtTime(.0001,now+dt+.42);s2.connect(sg);sg.connect(a.destination);s2.start(now+dt);s2.stop(now+dt+.44);}}
