const o=a.createOscillator(),g=a.createGain();o.type='square';o.frequency.setValueAtTime(260,now);o.frequency.exponentialRampToValueAtTime(1040,now+.07);o.frequency.exponentialRampToValueAtTime(520,now+.2);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.045,now+.012);g.gain.exponentialRampToValueAtTime(.0001,now+.22);o.connect(g);g.connect(a.destination);o.start(now);o.stop(now+.24);
